package site.hsu.hub.application.adapter.out.persistence;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="application_idempotency",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","recruitment_id","idempotency_key"}))public class IdempotencyEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="user_id",nullable=false)private Long userId;@Column(name="recruitment_id",nullable=false)private Long recruitmentId;@Column(name="idempotency_key",nullable=false,length=100)private String key;@Column(name="payload_hash",nullable=false,length=64)private String payloadHash;@Column(name="application_id",nullable=false)private Long applicationId;@Column(name="created_at",nullable=false)private Instant createdAt;protected IdempotencyEntity(){}public IdempotencyEntity(Long u,Long r,String key,String hash,Long app){userId=u;recruitmentId=r;this.key=key;payloadHash=hash;applicationId=app;createdAt=Instant.now();}public String payloadHash(){return payloadHash;}public Long applicationId(){return applicationId;}}
